//! OCSF's event classes as schemas, one a class, each named `ocsf/<class>`. The classes share OCSF's objects, as OCSF
//! does: one `user` object under every field whose type is a user. `ocsf_schema` is OCSF's own schema, every class
//! and object with every attribute it has, generated by `tools/ocsf-schema.sh`.

use std::sync::Arc;

use super::ocsf_schema::{ATTRS, CATEGORIES, CLASSES, OBJECTS, VERSION};
use super::{Field, Leaf, Objects, Origin, Reading, Schema, Type};

/// One attribute of a class or an object.
pub struct Attr {
    pub name: &'static str,
    pub ty: Ty,
    /// OCSF's name for the type, without its `_t`: `string`, `ip`, `timestamp`, `user`.
    pub type_name: &'static str,
    pub array: bool,
    pub required: bool,
    pub description: &'static str,
}

pub enum Ty {
    Str,
    Long,
    Float,
    Bool,
    /// `datetime_t`: RFC 3339 text, as the datetime profile writes a timestamp's `_dt` twin.
    DateTime,
    /// `timestamp_t`: milliseconds since the Unix epoch.
    EpochMillis,
    Json,
    /// The OCSF object of this name.
    Object(&'static str),
}

pub struct Object {
    pub name: &'static str,
    pub caption: &'static str,
    pub description: &'static str,
    /// Indexes into `ATTRS`, by name.
    pub attributes: &'static [u16],
}

pub struct Class {
    pub name: &'static str,
    /// The category's uid times 1000, plus the class's own.
    pub uid: u32,
    pub category: u32,
    pub caption: &'static str,
    pub description: &'static str,
    /// Indexes into `ATTRS`, by name.
    pub attributes: &'static [u16],
}

/// Each category's uid, name and caption.
pub fn categories() -> &'static [(u32, &'static str, &'static str)] {
    CATEGORIES
}

/// Every class as a schema, by class uid.
pub(super) fn schemas() -> Vec<Schema> {
    let mut objects = Objects::default();
    // Every object first, so that an attribute names any object by its index in `OBJECTS`.
    for o in OBJECTS {
        let at = objects.push(super::Object {
            name: o.name.to_string(),
            description: o.description.to_string(),
            fields: Vec::new(),
        });
        objects.name(o.name, at);
    }
    for (at, o) in OBJECTS.iter().enumerate() {
        objects.get_mut(at).fields = fields(o.attributes, &objects);
    }
    let roots: Vec<usize> = CLASSES
        .iter()
        .map(|c| {
            let fields = fields(c.attributes, &objects);
            objects.push(super::Object {
                name: c.name.to_string(),
                description: c.description.to_string(),
                fields,
            })
        })
        .collect();
    let shared: Arc<[super::Object]> = objects.into_shared();
    CLASSES
        .iter()
        .zip(roots)
        .map(|(c, root)| {
            Schema::new(
                format!("ocsf/{}", c.name),
                format!("OCSF {}", c.caption),
                c.description.to_string(),
                Origin::Ocsf {
                    version: VERSION,
                    class_uid: c.uid,
                    category: c.category,
                },
                Reading::Json,
                shared.clone(),
                root,
            )
        })
        .collect()
}

fn fields(attributes: &[u16], objects: &Objects) -> Vec<Field> {
    attributes
        .iter()
        .map(|&i| {
            let a = &ATTRS[i as usize];
            let ty = match a.ty {
                Ty::Str => Type::Leaf(Leaf::Str),
                Ty::Long => Type::Leaf(Leaf::Long),
                Ty::Float => Type::Leaf(Leaf::Float),
                Ty::Bool => Type::Leaf(Leaf::Bool),
                Ty::DateTime => Type::Leaf(Leaf::DateTime),
                Ty::EpochMillis => Type::Leaf(Leaf::EpochMillis),
                Ty::Json => Type::Leaf(Leaf::Json),
                // Every object an attribute names is one OCSF defines (`tests`).
                Ty::Object(name) => objects
                    .named(name)
                    .map_or(Type::Leaf(Leaf::Json), |at| Type::Object { at, implied: false }),
            };
            Field {
                name: a.name.to_string(),
                ty,
                type_name: a.type_name.to_string(),
                array: a.array,
                required: a.required,
                description: a.description.to_string(),
            }
        })
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_object_an_attribute_names_is_one_ocsf_defines() {
        for a in ATTRS {
            if let Ty::Object(name) = a.ty {
                assert!(
                    OBJECTS.binary_search_by(|o| o.name.cmp(name)).is_ok(),
                    "{}: no object {name}",
                    a.name
                );
            }
        }
    }

    #[test]
    fn every_class_is_a_schema_and_its_uid_is_its_categorys() {
        let schemas = schemas();
        assert_eq!(schemas.len(), CLASSES.len());
        for (c, s) in CLASSES.iter().zip(&schemas) {
            assert_eq!(c.uid / 1000, c.category);
            assert!(CATEGORIES.iter().any(|(uid, ..)| *uid == c.category));
            assert!(s.root().fields.iter().any(|f| f.name == "class_uid" && f.required));
        }
    }

    #[test]
    fn a_class_and_an_objects_attributes_are_sorted_and_unique() {
        let lists = OBJECTS
            .iter()
            .map(|o| o.attributes)
            .chain(CLASSES.iter().map(|c| c.attributes));
        for list in lists {
            let names: Vec<&str> = list.iter().map(|&i| ATTRS[i as usize].name).collect();
            assert!(names.windows(2).all(|w| w[0] < w[1]), "{names:?}");
        }
    }
}
